import{_ as n,C as l,o as c,c as d,ag as o,E as s,w as a,a as t,j as i}from"./chunks/framework.BSwSpTvy.js";const S=JSON.parse('{"title":"🧠 Long-Term Project Memory (SQLite)","description":"","frontmatter":{},"headers":[],"relativePath":"features/memory.md","filePath":"features/memory.md"}'),u={name:"features/memory.md"};function m(g,e,h,p,y,f){const r=l("ZedChat");return c(),d("div",null,[e[6]||(e[6]=o('<h1 id="🧠-long-term-project-memory-sqlite" tabindex="-1">🧠 Long-Term Project Memory (SQLite) <a class="header-anchor" href="#🧠-long-term-project-memory-sqlite" aria-label="Permalink to &quot;🧠 Long-Term Project Memory (SQLite)&quot;">​</a></h1><p>The Long-Term Memory system solves the &quot;context amnesia&quot; problem common in AI IDEs by persisting architectural decisions, recurring bugs, and project-specific patterns across editor restarts.</p><h2 id="architectural-overview" tabindex="-1">Architectural Overview <a class="header-anchor" href="#architectural-overview" aria-label="Permalink to &quot;Architectural Overview&quot;">​</a></h2><p>Unlike simple <code>.md</code> rule files that are always present in the prompt (leading to token bloat), this system uses a <strong>Retrival-Augmented Generation (RAG)</strong> approach backed by a local SQLite database.</p><p>Knowledge is structured into five distinct categories to help the agent maintain a clean conceptual map of your project:</p><ol><li><strong>Architecture</strong>: Core structural decisions.</li><li><strong>Patterns</strong>: Recurring code styles or library usage.</li><li><strong>Issues</strong>: Tricky bugs and their historical fixes.</li><li><strong>Procedures</strong>: Setup steps, build commands, and deployment flows.</li><li><strong>Notes</strong>: General project trivia.</li></ol><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><p>The core logic resides in <code>crates/agent/src/tools/memory_tools.rs</code>. The database is stored locally on your filesystem at <code>~/.local/share/zed/project_memory.db</code> (scoped by project path).</p><ul><li><strong>Fact Ingestion</strong>: The agent uses the <code>@remember</code> tool to write new rows using <code>INSERT OR REPLACE</code>.</li><li><strong>Fact Retrieval</strong>: The agent uses the <code>@recall</code> tool to execute <code>SELECT</code> queries, often triggered by a semantic search query or a category filter.</li></ul><h2 id="visual-walkthrough" tabindex="-1">Visual Walkthrough <a class="header-anchor" href="#visual-walkthrough" aria-label="Permalink to &quot;Visual Walkthrough&quot;">​</a></h2><h3 id="step-1-learning-a-new-constraint" tabindex="-1">Step 1: Learning a New Constraint <a class="header-anchor" href="#step-1-learning-a-new-constraint" aria-label="Permalink to &quot;Step 1: Learning a New Constraint&quot;">​</a></h3>',11)),s(r,null,{user:a(()=>[...e[0]||(e[0]=[t(' We must use the "Service Layer" pattern for all database interactions in this crate. Never call Postgres queries directly from the UI. ',-1)])]),assistant:a(()=>[...e[1]||(e[1]=[t(" Understood. Storing this architectural rule in the project memory. ",-1)])]),output:a(()=>[...e[2]||(e[2]=[t(' @remember({ category: "Architecture", content: "Strictly use Service Layer pattern for DB interactions. UI must not call Postgres directly." }) ',-1)])]),_:1}),e[7]||(e[7]=i("h3",{id:"step-2-recalling-context-in-a-new-session",tabindex:"-1"},[t("Step 2: Recalling Context in a New Session "),i("a",{class:"header-anchor",href:"#step-2-recalling-context-in-a-new-session","aria-label":'Permalink to "Step 2: Recalling Context in a New Session"'},"​")],-1)),s(r,null,{user:a(()=>[...e[3]||(e[3]=[t(" I'm ready to add the User Profile page. How should I handle the database part? ",-1)])]),assistant:a(()=>[...e[4]||(e[4]=[t(" Checking project memory for database patterns... ",-1)])]),output:a(()=>[...e[5]||(e[5]=[t(' @recall({ query: "database pattern" }) >> Found in [Architecture]: "Strictly use Service Layer pattern for DB interactions..." ',-1)])]),_:1}),e[8]||(e[8]=o('<h2 id="comparison-sqlite-vs-md-files" tabindex="-1">Comparison: SQLite vs .md Files <a class="header-anchor" href="#comparison-sqlite-vs-md-files" aria-label="Permalink to &quot;Comparison: SQLite vs .md Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Standard IDEs (.md)</th><th style="text-align:left;">Zed Custom (SQLite)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Token Usage</strong></td><td style="text-align:left;">Constant / Exponential</td><td style="text-align:left;">Minimal (Selective Retrieval)</td></tr><tr><td style="text-align:left;"><strong>Searchability</strong></td><td style="text-align:left;">Linear Text Scan</td><td style="text-align:left;">Structured SQL/Semantic Search</td></tr><tr><td style="text-align:left;"><strong>Scaling</strong></td><td style="text-align:left;">Fails at large rule-sets</td><td style="text-align:left;">Handles thousands of project facts</td></tr></tbody></table><h2 id="workflow-impact" tabindex="-1">Workflow Impact <a class="header-anchor" href="#workflow-impact" aria-label="Permalink to &quot;Workflow Impact&quot;">​</a></h2><ul><li><strong>Eliminate Regressions</strong>: The agent proactively warns you if you attempt to re-implement a pattern that was previously archived as &quot;problematic.&quot;</li><li><strong>Institutional Knowledge</strong>: New developers joining the project gain an instant &quot;AI mentor&quot; that remembers every architectural pivots and obscure bug fix.</li><li><strong>Context Management</strong>: Drastically reduces the &quot;Recap Phase&quot; at the start of every session. The agent starts with a warm cache of project-specific facts.</li><li><strong>Precision Grounding</strong>: Unlike generic LLM training, these memories ensure the agent follows <em>your</em> repository&#39;s unique conventions.</li></ul>',4))])}const x=n(u,[["render",m]]);export{S as __pageData,x as default};
